import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"1D Packing · BPP1D","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp1d/index.md","filePath":"frameworks/bpp1d/index.md"}'),o={name:"frameworks/bpp1d/index.md"};function r(l,e,d,c,s,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_1d-packing-·-bpp1d" tabindex="-1">1D Packing · BPP1D <a class="header-anchor" href="#_1d-packing-·-bpp1d" aria-label="Permalink to &quot;1D Packing · BPP1D&quot;">​</a></h1><p>Pack existing long items into length-limited slots. Container types have length, weight capacity, cost and inventory; adjacent items may need spacing. BPP1D selects loading patterns and produces independently checkable placements.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Item</td><td><code>Item</code></td><td>Stable ID, length, weight and exact count</td></tr><tr><td>Container type</td><td><code>BinType</code></td><td>Length, load capacity, cost and optional stock</td></tr><tr><td>Problem</td><td><code>PackingProblem</code></td><td>Items, containers, spacing and objective</td></tr><tr><td>Loading pattern</td><td><code>PackingPattern</code></td><td>Counts of each item in one container</td></tr><tr><td>Final result</td><td><code>PackingResult</code></td><td>Placements, free intervals, materials and KPIs</td></tr></tbody></table><p>Spacing occurs only between adjacent items, not after the last item. Preserve units: <code>40 cm</code> cannot be compared directly with an unqualified <code>1</code>.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Kotlin injects <code>ColumnGenerationSolver</code> and a numeric adapter into <code>Bpp1dMilp</code> / <code>Bpp1dColumnGeneration</code>. Rust&#39;s similarly named application entries receive actual solver models through callbacks; do not translate constructors and error handling line by line.</p><p>You own data, objectives and backend configuration. The framework owns pattern generation, registration, selection and packing validation. Start with ordinary MILP before column generation.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>This models existing items. Compare <a href="./../csp1d/">CSP1D</a> for material processing, production contributions and production deviations.</li><li>Candidate enumeration can be bounded by nodes and pattern counts. Read <code>complete</code>; do not assume it.</li><li>LP pricing termination is not integer optimality; restricted-pool optimality is not automatically global optimality.</li><li>Tail repacking must validate the full plan. Global-only business rules cannot simply become local subproblem rules.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-packing.html">your first 1D packing</a> for input, solving, placements and quantity checks.</li><li>Add spacing, inventory, multiple types and costs to the same scenario, then inspect extension contracts.</li><li>Read the <a href="/ospf/guide/modeling-workflow.html">modeling workflow</a> when custom modeling is needed; do not duplicate domain formulas in the application service.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp1d/README.md" target="_blank" rel="noreferrer">Kotlin API and extension contracts</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp1d/README.md" target="_blank" rel="noreferrer">Rust API and extension contracts</a></li><li><a href="/ospf/guide/solving-results.html">Understanding solver results</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Container Types, Stock and Cost</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const h=t(o,[["render",r]]);export{u as __pageData,h as default};
